using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Threading;
using QuietCare;

internal static class CareTests {
    static int passed,failed;
    static void Check(bool value,string message){if(!value)throw new Exception(message);}
    static void Test(string name,Action test){try{test();passed++;Console.WriteLine("PASS "+name);}catch(Exception ex){failed++;Console.WriteLine("FAIL "+name+": "+ex);}}
    sealed class Progress : IProgress<CareProgress>{public readonly List<CareProgress> Rows=new List<CareProgress>();public Action<CareProgress> Action;public void Report(CareProgress p){Rows.Add(p);if(Action!=null)Action(p);}}
    sealed class Checks : ICareChecks {public readonly List<string> Called=new List<string>();public Func<string,CancellationToken,CareCheckResult> Run;public CareCheckResult Check(string id,Action<string,string> progress,CancellationToken cancel){Called.Add(id);progress("Checking fixture",id);return Run==null?new CareCheckResult{Summary="Fixture observed"}:Run(id,cancel);}}
    static int Main(string[] args){
        string fixture=args[0];State.DirectoryPath=Path.Combine(fixture,"State");Directory.CreateDirectory(fixture);
        Test("All selected real categories report running and final states",()=>{var checks=new Checks();var progress=new Progress();var result=new CareScanner(checks).Run(CareScanner.Ids,progress,CancellationToken.None);Check(result.Results.Count==6&&!result.Stopped,"Missing result");Check(progress.Rows.Count(x=>x.State==CareState.Running)>=6,"No live start events");Check(progress.Rows.Last().Completed==6&&progress.Rows.Last().Total==6,"Wrong completed count");Check(checks.Called.SequenceEqual(CareScanner.Ids),"Unexpected order");});
        Test("Unselected checks are skipped without being executed",()=>{var checks=new Checks();var progress=new Progress();var result=new CareScanner(checks).Run(new[]{"memory","storage"},progress,CancellationToken.None);Check(checks.Called.SequenceEqual(new[]{"memory","storage"}),"Unselected check executed");Check(result.Results.Count==2&&progress.Rows.Last().Total==2,"Wrong selection denominator");});
        Test("A failed category is unavailable and later categories still run",()=>{var checks=new Checks{Run=(id,cancel)=>{if(id=="startup")throw new IOException("Fixture denied");return new CareCheckResult{Summary="Observed"};}};var result=new CareScanner(checks).Run(new[]{"startup","memory"},null,CancellationToken.None);Check(result.Results[0].State==CareState.Unavailable&&result.Results[1].State==CareState.Complete,"Failed step marked clean or halted scan");});
        Test("Stop preserves completed results and does not run remaining checks",()=>{var cancel=new CancellationTokenSource();var checks=new Checks{Run=(id,token)=>{if(id=="startup"){cancel.Cancel();token.ThrowIfCancellationRequested();}return new CareCheckResult{Summary="Observed"};}};var result=new CareScanner(checks).Run(CareScanner.Ids,null,cancel.Token);Check(result.Stopped&&result.Results.Count==1,"Partial report lost");Check(checks.Called.Count==2,"Stopped scan continued");});
        Test("Skip cancels only the current category and continues",()=>{var checks=new Checks();CareScanner scanner=null;var progress=new Progress{Action=p=>{if(p.Id=="temp"&&p.State==CareState.Running)scanner.SkipCurrent();}};checks.Run=(id,cancel)=>{cancel.ThrowIfCancellationRequested();return new CareCheckResult{Summary="Observed"};};scanner=new CareScanner(checks);var result=scanner.Run(new[]{"temp","memory"},progress,CancellationToken.None);Check(!result.Stopped&&result.Results[0].State==CareState.Skipped&&result.Results[1].State==CareState.Complete,"Skip stopped entire scan");});
        Test("An empty selection never runs checks",()=>{var checks=new Checks();bool rejected=false;try{new CareScanner(checks).Run(new string[0],null,CancellationToken.None);}catch(InvalidOperationException){rejected=true;}Check(rejected&&checks.Called.Count==0,"Empty scan allowed");});
        Test("Temp progress reports real candidates and keeps original bytes",()=>{string temp=Path.Combine(fixture,"Temp");Directory.CreateDirectory(temp);string old=Path.Combine(temp,"old.tmp"),keep=Path.Combine(temp,"project.txt");File.WriteAllText(old,"old fixture");File.SetLastWriteTimeUtc(old,DateTime.UtcNow.AddDays(-10));File.WriteAllText(keep,"project data");var cleaner=new Cleaner(temp,Path.Combine(fixture,"Recovery"));var events=new List<ScanFileProgress>();var scan=cleaner.Scan(CancellationToken.None,events.Add);Check(scan.Items.Count==1&&events.Last().Candidates==1&&events.Last().Bytes==scan.Bytes,"Progress differs from results");Check(events.Last().Examined==2,"Wrong examined count");Check(File.ReadAllText(old)=="old fixture"&&File.ReadAllText(keep)=="project data","Preview changed files");});
        Test("Temp Care result carries the actual cleanup preview",()=>{var native=new WindowsCareChecks(new Cleaner(Path.Combine(fixture,"Temp"),Path.Combine(fixture,"Recovery")));var result=native.Check("temp",(text,path)=>{},CancellationToken.None);Check(result.TempFiles!=null&&result.Count==1&&result.Findings.Count==1,"Cleanup context missing");});
        if(args.Contains("--live"))Test("Live six-category read-only Care scan reports honest outcomes",()=>{var events=new Progress();var result=new CareScanner().Run(CareScanner.Ids,events,CancellationToken.None);Check(result.Results.Count==6&&!result.Stopped,"Live scan incomplete");foreach(var item in result.Results)Console.WriteLine("  LIVE "+item.Name+": "+item.State+" · "+item.Count+" observations/candidates");Check(result.Results.All(x=>x.State==CareState.Complete||x.State==CareState.Partial||x.State==CareState.Unavailable),"Incorrect final state");});
        Console.WriteLine("CARE RESULT "+passed+" passed / "+failed+" failed");return failed==0?0:1;
    }
}
